def transform(grid):
    from collections import deque
    h, w = len(grid), len(grid[0])
    seen = set()
    counts = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            counts[color] = counts.get(color, 0) + 1
            q = [(r, c)]
            seen.add((r, c))
            while q:
                y, x = q.pop()
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == color and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))
    vals = []
    for color in sorted(counts):
        vals.extend([color] * counts[color])
    width = max(1, (len(vals) + 1) // 2)
    vals += [0] * (2 * width - len(vals))
    return [vals[:width], vals[width:]]
